    public function __construct(){
        $empresas = NasajonEstabelecimento::orderBy('codigo')->get();

        foreach ($empresas as $key => $empresa) {
            if(in_array($empresa->codigo, ['99', 'TREINAMENTO'])){
               continue; 
            }
            $estabelecimentos[$empresa->codigo] = str_pad($empresa->codigo, 2, "0", STR_PAD_LEFT)." - ".$empresa->nomefantasia;
        }
        
        $this->estabelecimentos = $estabelecimentos;
    }
    /**
     * Display a listing of the resource.
     *
     * @return \Illuminate\Http\Response
     */
    public function index(Request $request){
        if(Auth::user()->hasPermissionTo("programas App\FluxoDeCaixa") === false){
            return abort(403);
        }
        $request->session()->flash('model', 'App\FluxoDeCaixa');
        $estabelecimentos = $this->estabelecimentos;
        return view('programs.fluxo_caixa.index')->with(['estabelecimentos' => $estabelecimentos]);
    }


    public function filter(FluxoDeCaixaFilterRequest $request, $array = false){
