        $fields = $request->only(['data_inicio', 'data_fim', 'armazen', 'intercompany', 'cambio', 'nacionalizacao', 'duvidosos', 'cheques', 'juros',
        '00','01','02','03','04','05','06','07','08','20','25','MARCELO','MN_NAMURA','NAMURA_NN','NELSON']);
        
        if(!empty($fields['armazen'])){
            if($fields['armazen'] == "false"){
