        $ultimo_dia_do_mes = Carbon::createFromFormat('d/m/Y', $data_fim)->setTime(0,0,0)->lastOfMonth();

        $data_inicio = Carbon::createFromFormat('d/m/Y', $data_inicio)->setTime(0,0,0);
        $data_fim = Carbon::createFromFormat('d/m/Y', $data_fim)->setTime(23,59,59);

        $query_orcamento = OrcamentoCompra::select(DB::Raw('data, tipo, SUM(valor) AS valor'));
        $query_orcamento->whereBetween('data', [$primeiro_dia_do_mes, $ultimo_dia_do_mes]);
        $query_orcamento->where('modo', 'fluxo_caixa');
        $query_orcamento->whereIn('tipo', ['nacional', 'importado', 'uso_consumo', 'banco', 'despesas']);
        $query_orcamento->groupBy('data', 'tipo');
        $result_orcamentos = $query_orcamento->get();

        $EntradaDeCaixaObj = EntradaDeCaixa::select('data', DB::Raw('SUM(valor_inicial) AS valor_inicial'))
