            ->groupBy('data');

        $TitulosAPagarNasajonObj = TitulosAPagarNasajon::select(DB::Raw('"Data do Vencimento" AS data_vencimento, case 
            when "Situação do Título" = \'Aberto\' then SUM("Saldo")
            when "Situação do Título" = \'Em Débito\' then SUM("Saldo") end as valor '))
            ->whereBetween('Data do Vencimento', [$data_inicio, $data_fim])
            ->whereIn('Situação do Título', ['Aberto', 'Em Débito'])
            ->groupBy('Data do Vencimento', 'Situação do Título');

        $TitulosAPagarNasajonQuitadoObj = TitulosAPagarNasajon::select(DB::Raw('
            "Data do Vencimento" as data_vencimento,
