                $response[$key]['valor_saldo'] = floatval($value['valor_saldo']);
                $response[$key]['valor_saldo_acumulado'] = floatval($value['valor_saldo_acumulado']);
                $response[$key]['valor_previsao'] = floatval($value['valor_previsao']);
                $response[$key]['valor_previsao_acumulado'] = floatval($value['valor_previsao_acumulado']);
            }

            if(strtolower($response[$key]['data']) !== 'disponivel'){
                $criterios_areceber = encrypt([
                    'key' => 'a_receber',
                    'buscas' => $fields,
                    'data' => $response[$key]['data']
                ]);
                $criterios_apagar = encrypt([
                    'key' => 'a_pagar',
                    'buscas' => $fields,
                    'data' => $response[$key]['data']
                ]);
                if($array == true){
                    $response[$key]['valor_a_receber'] = ($response[$key]['valor_a_receber'] != '0,00')?$response[$key]['valor_a_receber']:'';
                    $response[$key]['valor_a_pagar'] = ($response[$key]['valor_a_pagar'] != '0,00')?$response[$key]['valor_a_pagar']:'';
                }else{
                    $response[$key]['valor_a_receber'] = ($response[$key]['valor_a_receber'] != '0,00')?'<a href="#" onclick="openDadosFluxo(\'' . $criterios_areceber . '\', \'Contas a receber do dia '.$response[$key]['data'].'\')">' . $response[$key]['valor_a_receber'] . '</a>': '';
                    $response[$key]['valor_a_pagar'] = ($response[$key]['valor_a_pagar'] != '0,00')?'<a href="#" onclick="openDadosFluxo(\'' . $criterios_apagar . '\', \'Contas a pagar do dia '.$response[$key]['data'].'\')">' . $response[$key]['valor_a_pagar'] . '</a>': '';
