        $total['valor_a_receber'] = parserValor($total['valor_a_receber']);
        $total['valor_a_pagar'] = parserValor($total['valor_a_pagar']);
        $total['valor_previsao'] = parserValor($total['valor_previsao']);

        $criterios_areceber_total = encrypt([
            'key' => 'a_receber_total',
