        }

        if($array == true){
            return $response;
        }
        else{
            $return = [
                'status' => 'success',
                'message' => '',
                'error' => [],
                'response' => [
                    'saida' => $response,
                    'total' => $total
                ]
            ];
            return response()->json($return);
        }
    }

