            }
            $total = parserValor($total);

            if($criterios['key'] === 'a_receber'){
                return view('programs.fluxo_caixa.modal.dados')->with(['response' => $response, 'data' => 'Contas a Receber do dia '.$criterios['data'], 'cliente_fornecedor' => 'Cliente', 'total' => $total]);
