            }

        }
        if($criterios['key'] === 'a_pagar' || $criterios['key'] === 'a_pagar_total'){
            $titulos_a_pagar = $TitulosAPagarNasajonObj->get();
            $response = [];
            
            foreach ($titulos_a_pagar as $key => $titulo) {
