    }

    public function modalPrevisaoTituloFornecedor(Request $request){
        $fields = $request->only(['fornecedor_codigo', 'data_inicio', 'data_fim']);
        
        $data_inicio = Carbon::parse($fields['data_inicio'])->setTime(0,0,0);
        $data_fim = Carbon::parse($fields['data_fim'])->setTime(23,59,59);

        $codigos_excluir = [];
        $cnpj_excluir = [];
            
        $codigos_excluir[] = '0050758840001';
        $cnpj_excluir[] = '05075884000167';
        $codigos_excluir[] = '0050758840002';
        $cnpj_excluir[] = '05075884000248';

        $codigos_excluir[] = '0063112740002';
        $cnpj_excluir[] = '06311274000269';
        $codigos_excluir[] = '0063112740003';
        $codigos_excluir[] = '06311274000340';
        $cnpj_excluir[] = '06311274000340';

        $cnpj_excluir[] = '08';
        $cnpj_excluir[] = '07';
        $codigos_excluir[] = '08';
        $codigos_excluir[] = '07';
        $cnpj_excluir[] = '06311274000501';
        $codigos_excluir[] = '06311274000501';
        $cnpj_excluir[] = '06311274000420';
        $codigos_excluir[] = '06311274000420';
        $codigos_excluir[] = '0000021019999';
        $codigos_excluir[] = '0000021139999';
        $codigos_excluir[] = '0000309269999';

        $TitulosAPagarNasajonObj = TitulosAPagarNasajon::select()
            ->where("Fornecedor", $fields['fornecedor_codigo'])
            ->whereIn('Situação do Título', ['Aberto', 'Em Débito', 'Quitado'])
            ->whereBetween('Data do Vencimento', [$data_inicio, $data_fim]);

        $TitulosAPagarNasajonObj->whereNotIn("Fornecedor", $codigos_excluir);

        $TitulosAPagarNasajonObj = $TitulosAPagarNasajonObj->get();
        
        $titulos = [];
        $total = 0;
        foreach($TitulosAPagarNasajonObj as $value){
            $titulos[] = [
                'estabelecimento' => $value["Estabelecimento"].' - '.$value["Nome do Estabelecimento"],
                'numero' => $value["Número do Título"],
                'data_emissao' => parserData($value["Data de Emissão"]),
                'data_vencimento' => parserData($value["Data do Vencimento"]),
                'data_baixa' => empty($value["Data da Baixa"])? '' : parserData($value["Data da Baixa"]),
                'valor' => parserValor($value["Valor"]),
                'situacao' => $value["Situação do Título"],
                'data_emissao_codigo' => $value["Data de Emissão"],
                'data_vencimento_codigo' => $value["Data do Vencimento"],
                'data_baixa_codigo' => empty($value["Data da Baixa"])? '' : $value["Data da Baixa"],
            ];

            $total += $value["Valor"];
        }

        $total = empty($total)? '' : parserValor($total);

        return view('programs.fluxo_caixa.modal.previsao_fornecedor')->with(['titulos' => $titulos, 'total' => $total]);
    }
